export interface PricingTableFourProps
  extends VariantProps<typeof sectionVariants> {
  billingToggleLabels?: {
    monthly: string
    yearly: string
  }
  className?: string
  description?: string
  onPlanSelect?: (planId: string) => void
  plans: Plan[]
  showBillingToggle?: boolean
  subtitle?: string
  title?: string
}

const defaultIcons = {
  starter: <Package className="h-4 w-4" />,
  pro: <Award className="h-4 w-4" />,
  enterprise: <Building2 className="h-4 w-4" />,
}

export function PricingTableFour({
  plans,
  title = "Choose Your Perfect Plan",
  description = "Transform your project with our comprehensive pricing options designed for every need.",
  subtitle,
  onPlanSelect,
  className,
  size = "medium",
  theme = "minimal",
  showBillingToggle = true,
  billingToggleLabels = {
    monthly: "Monthly",
    yearly: "Yearly",
  },
}: PricingTableFourProps) {
  const [isAnnually, setIsAnnually] = useState(false)
  const uniqueId = useId()

  function calculateDiscount(
    monthlyPrice: string,
    yearlyPrice: string,
  ): number {
    const monthly = Number.parseFloat(monthlyPrice)
    const yearly = Number.parseFloat(yearlyPrice)

    if (
      monthlyPrice.toLowerCase() === "custom" ||
      yearlyPrice.toLowerCase() === "custom" ||
      Number.isNaN(monthly) ||
      Number.isNaN(yearly) ||
      monthly === 0
    ) {
      return 0
    }

    const discount = ((monthly * 12 - yearly) / (monthly * 12)) * 100
    return Math.round(discount)
  }

  const yearlyPriceDiscount = plans.length
    ? Math.max(
        ...plans.map((plan) =>
          calculateDiscount(plan.monthlyPrice, plan.yearlyPrice),
        ),
      )
    : 0

  const handlePlanSelect = (planId: string) => {
    onPlanSelect?.(planId)
  }

  const getPlanIcon = (planId: string) =>
    defaultIcons[planId as keyof typeof defaultIcons] || (
      <Package className="h-5 w-5" />
    )

  return (
    <section className={cn(sectionVariants({ size, theme }), className)}>
      {/* Classic theme background elements */}
      {theme === "classic" && (
        <>
          <div className="absolute inset-0 bg-grid-pattern opacity-5" />
          <div className="absolute start-1/2 top-1/2 h-96 w-96 -translate-y-1/2 rounded-full bg-primary/5 blur-3xl ltr:-translate-x-1/2 rtl:translate-x-1/2" />
          <div className="absolute end-1/4 top-1/4 h-64 w-64 rounded-full bg-secondary/5 blur-2xl" />
        </>
      )}

      <div className="container relative mx-auto max-w-7xl">
        {/* Header */}
        <div className="mb-12 text-center">
          {subtitle && (
            <p className="mb-3 font-medium text-primary text-sm uppercase tracking-wide">
              {subtitle}
            </p>
          )}
          <h2 className={cn(titleVariants({ size, theme }))}>{title}</h2>
          <p className={cn(descriptionVariants({ size, theme }))}>
            {description}
          </p>

          {showBillingToggle && (
            <div
              className={cn(
                "mx-auto mt-8 flex justify-center",
                toggleVariants({ theme }),
              )}
            >
              <RadioGroup
                className="h-full grid-cols-2"
                defaultValue="monthly"
                onValueChange={(value) => {
                  setIsAnnually(value === "annually")
                }}
              >
                <div className='h-full rounded-md transition-all has-[button[data-state="checked"]]:bg-background'>
                  <RadioGroupItem
                    className="peer sr-only"
                    id={`${uniqueId}-monthly`}
                    value="monthly"
                  />
                  <Label
                    className="flex h-full cursor-pointer items-center justify-center px-2 font-semibold text-muted-foreground transition-all hover:text-foreground peer-data-[state=checked]:text-primary md:px-7"
                    htmlFor={`${uniqueId}-monthly`}
                  >
                    {billingToggleLabels.monthly}
                  </Label>
                </div>
                <div className='h-full rounded-md transition-all has-[button[data-state="checked"]]:bg-background'>
                  <RadioGroupItem
                    className="peer sr-only"
                    id={`${uniqueId}-annually`}
                    value="annually"
                  />
                  <Label
                    className="flex h-full cursor-pointer items-center justify-center gap-1 px-2 font-semibold text-muted-foreground transition-all hover:text-foreground peer-data-[state=checked]:text-primary md:px-7"
                    htmlFor={`${uniqueId}-annually`}
                  >
                    {billingToggleLabels.yearly}
                    {yearlyPriceDiscount > 0 && (
                      <span className="ms-1 rounded border border-primary/20 bg-primary/10 px-2 py-0.5 font-medium text-primary text-xs">
                        Save {yearlyPriceDiscount}%
                      </span>
                    )}
                  </Label>
                </div>
              </RadioGroup>
            </div>
          )}
        </div>

        <div
          className={cn(
            "grid gap-6",
            plans.length === 1 && "mx-auto max-w-md grid-cols-1",
            plans.length === 2 &&
              "mx-auto max-w-4xl grid-cols-1 md:grid-cols-2",
            plans.length === 3 && "grid-cols-1 md:grid-cols-3",
            plans.length >= 4 &&
              "grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4",
          )}
        >
          {plans.map((plan, index) => (
            <motion.div
              animate={{ opacity: 1, y: 0 }}
              className="group relative h-full"
              initial={{ opacity: 0, y: 20 }}
              key={plan.id}
              transition={{
                duration: 0.4,
                delay: index * 0.1,
                ease: "easeOut",
              }}
            >
              {/* Popular badge */}
              {plan.badge && (
                <Badge
                  className={cn(
                    "absolute start-1/2 -top-3 z-20 transform ltr:-translate-x-1/2 rtl:translate-x-1/2",
                    theme === "classic"
                      ? "border-primary/20 bg-gradient-to-r from-primary to-primary/80 text-primary-foreground shadow-lg"
                      : "bg-primary text-primary-foreground",
                  )}
                >
                  {plan.badge}
                </Badge>
              )}

              {/* Classic theme highlight effect */}
              {theme === "classic" && plan.highlight && (
                <div className="absolute start-1/2 -top-px h-px w-32 bg-gradient-to-r from-transparent via-primary to-transparent ltr:-translate-x-1/2 rtl:translate-x-1/2" />
              )}

              <div
                className={cn(
                  cardVariants({ size, theme, highlight: plan.highlight }),
                )}
              >
                <div className="flex h-full flex-col">
                  {/* Icon and Title */}
                  <div className="mb-4 flex items-start gap-4">
                    <div className="flex-1">
                      <h3
                        className={cn(
                          "mb-1 font-bold text-xl",
                          theme === "classic" ? "text-lg" : "",
                        )}
                      >
                        {plan.title}
                      </h3>
                      <p
                        className={cn(
                          "text-muted-foreground text-sm",
                          theme === "classic" && "text-foreground/80",
                        )}
                      >
                        {plan.description}
                      </p>
                    </div>
                    <div
                      className={cn(
                        "flex h-10 w-10 flex-shrink-0 items-center justify-center rounded-lg",
                        theme === "classic"
                          ? "border border-primary/20 bg-primary/10 text-primary"
                          : "border border-border bg-muted text-foreground",
                      )}
                    >
                      {getPlanIcon(plan.id)}
                    </div>
                  </div>

                  {/* Price */}
                  <div className="mb-6">
                    <AnimatePresence mode="wait">
                      <motion.div
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: -10 }}
                        initial={{ opacity: 0, y: 10 }}
                        key={isAnnually ? "year" : "month"}
                        transition={{ duration: 0.2 }}
                      >
                        {isAnnually ? (
                          <div className="flex items-baseline gap-1">
                            <span
                              className={cn(priceTextVariants({ size, theme }))}
                            >
                              {Number.parseFloat(plan.yearlyPrice) >= 0 &&
                                plan.yearlyPrice.toLowerCase() !== "custom" &&
                                plan.currency}
                              {plan.yearlyPrice}
                            </span>
                            <span className="text-muted-foreground text-sm">
                              /year
                            </span>
                            {calculateDiscount(
                              plan.monthlyPrice,
                              plan.yearlyPrice,
                            ) > 0 && (
                              <span
                                className={cn(
                                  "ms-2 text-xs",
                                  theme === "classic"
                                    ? "font-semibold text-emerald-500"
                                    : "font-medium text-primary",
                                )}
                              >
                                {calculateDiscount(
                                  plan.monthlyPrice,
                                  plan.yearlyPrice,
                                )}
                                % off
                              </span>
                            )}
                          </div>
                        ) : (
                          <div className="flex items-baseline gap-1">
                            <span
                              className={cn(priceTextVariants({ size, theme }))}
                            >
                              {Number.parseFloat(plan.monthlyPrice) >= 0 &&
                                plan.monthlyPrice.toLowerCase() !==
                                  "custom" && <>{plan.currency}</>}
                              {plan.monthlyPrice}
                            </span>
                            <span className="text-muted-foreground text-sm">
                              /month
                            </span>
                          </div>
                        )}
                      </motion.div>
                    </AnimatePresence>
                  </div>

                  {/* CTA Button */}
                  <div className="mb-6">
                    <Button
                      className={cn(
                        buttonVariants({ theme }),
                        !plan.highlight &&
                          theme === "minimal" &&
                          "bg-secondary text-secondary-foreground hover:bg-secondary/80",
                      )}
                      onClick={() => handlePlanSelect(plan.id)}
                      variant={plan.highlight ? "default" : "secondary"}
                    >
                      {plan.buttonText}
                      {theme === "classic" && plan.highlight && (
                        <div className="absolute inset-0 translate-x-[-100%] bg-gradient-to-r from-white/0 via-white/10 to-white/0 transition-transform duration-700 hover:translate-x-[100%]" />
                      )}
                    </Button>
                  </div>

                  {/* Features */}
                  <div className="flex-1">
                    <ul className="space-y-3">
                      {plan.features.map((feature, featureIndex) => (
                        <motion.li
                          animate={{ opacity: 1, x: 0 }}
                          className="flex items-start gap-3"
                          initial={{ opacity: 0, x: -10 }}
                          // biome-ignore lint/suspicious/noArrayIndexKey: safe to use
                          key={featureIndex}
                          transition={{
                            duration: 0.3,
                            delay: featureIndex * 0.05,
                          }}
                        >
                          <Check
                            className={cn(featureIconVariants({ size, theme }))}
                          />
                          <span
                            className={cn(
                              "text-sm",
                              theme === "classic"
                                ? "text-foreground/90"
                                : "text-muted-foreground",
                            )}
                          >
                            {feature.name}
                          </span>
                        </motion.li>
                      ))}
                    </ul>
                  </div>
                </div>
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  )
}

import { beforeEach, describe, expect, test, vi } from "vitest"
import { invalidateCacheKeys, withCache } from "../src/cache-utils"

const mocks = vi.hoisted(() => {
  // In-memory stand-in that replicates the real store's JSON round-trip so
  // the tests exercise the serialization behavior withCache depends on.
  const redisData = new Map<string, string>()
  return {
    redisData,
    distributedStore: {
      get: vi.fn((key: string) => {
        const value = redisData.get(key)
        return Promise.resolve(value ? JSON.parse(value) : null)
      }),
      put: vi.fn((key: string, value: unknown) => {
        redisData.set(key, JSON.stringify(value))
        return Promise.resolve()
      }),
      sadd: vi.fn(() => Promise.resolve(1)),
      expire: vi.fn(() => Promise.resolve(1)),
      delete: vi.fn((keys: string | string[]) => {
        const keysArray = Array.isArray(keys) ? keys : [keys]
        for (const key of keysArray) {
          redisData.delete(key)
        }
        return Promise.resolve()
      }),
    },
  }
})

vi.mock("../src/index.ts", () => ({
  distributedStore: mocks.distributedStore,
}))

vi.mock("@chatbotx.io/logger", () => ({
  default: { debug: vi.fn() },
}))

describe("withCache", () => {
  beforeEach(() => {
    mocks.redisData.clear()
    vi.clearAllMocks()
  })

  test("preserves Date instances across the cache round-trip", async () => {
    const workspace = {
      id: "1",
      name: "Acme",
      createdAt: new Date("2026-07-01T00:00:00.000Z"),
      scheduledDeletionAt: null,
    }

    const firstResult = await withCache("workspaces:1", () =>
      Promise.resolve(workspace),
    )
    expect(firstResult).toEqual(workspace)

    const source = vi.fn()
    const cachedResult = await withCache<typeof workspace>(
      "workspaces:1",
      source,
    )
    expect(source).not.toHaveBeenCalled()
    expect(cachedResult.createdAt).toBeInstanceOf(Date)
    expect(cachedResult).toEqual(workspace)
  })

  test("ignores legacy plain-JSON entries written under unprefixed keys", async () => {
    mocks.redisData.set(
      "workspaces:legacy",
      JSON.stringify({ id: "1", createdAt: "2026-07-01T00:00:00.000Z" }),
    )

    const fresh = { id: "1", createdAt: new Date("2026-07-01T00:00:00.000Z") }
    const result = await withCache("workspaces:legacy", () =>
      Promise.resolve(fresh),
    )
    expect(result).toBe(fresh)
  })

  test("registers tags against the prefixed cache key", async () => {
    await withCache("workspaces:1", () => Promise.resolve({ id: "1" }), {
      dynamicTags: (result) => [`workspaces:${result.id}`],
    })

    expect(mocks.distributedStore.sadd).toHaveBeenCalledWith(
      "tags:workspaces:1",
      "sj:workspaces:1",
    )
  })

  test("invalidateCacheKeys removes entries stored by withCache", async () => {
    await withCache("workspaces:1", () => Promise.resolve({ id: "1" }))
    // Legacy entry from a pre-SuperJSON writer under the unprefixed key.
    mocks.redisData.set("workspaces:1", JSON.stringify({ id: "1" }))

    await invalidateCacheKeys("workspaces:1")

    expect(mocks.redisData.size).toBe(0)
    const source = vi.fn(() => Promise.resolve({ id: "2" }))
    const result = await withCache("workspaces:1", source)
    expect(source).toHaveBeenCalledTimes(1)
    expect(result).toEqual({ id: "2" })
  })

  test("does not cache null or undefined results", async () => {
    const result = await withCache("workspaces:missing", () =>
      Promise.resolve(undefined),
    )
    expect(result).toBeUndefined()
    expect(mocks.distributedStore.put).not.toHaveBeenCalled()
  })
})

