  username: string
  userId: string
  profile_picture_url?: string
  accessToken: string
}

export function generateAuthUrl({
  clientId,
  redirectUrl,
  stateParams,
}: {
  clientId: string
  version?: string
  redirectUrl: string
  stateParams?: Record<string, unknown>
}): string {
  const params = new URLSearchParams({
    client_id: clientId,
    redirect_uri: redirectUrl,
    response_type: "code",
    state: Buffer.from(JSON.stringify(stateParams ?? {})).toString("base64"),
    scope: INSTAGRAM_BUSINESS_SCOPES.join(","),
  })
  return `${INSTAGRAM_OAUTH_AUTHORIZE_URL}?${params.toString()}`
}

// Step 1: exchange authorization code → short-lived user access token + user ID
export function exchangeCodeForToken(
  settings: { clientId: string; clientSecret: string; version?: string },
  code: string,
  redirectUrl: string,
): Promise<{ accessToken: string; userId: string }> {
  const endpoint = "oauth/access_token"

  return rescue(endpoint, async () => {
    const res: { access_token: string; user_id: string | number } =
      await instagramOAuthClient.post(endpoint, {
        body: new URLSearchParams({
          client_id: settings.clientId,
          client_secret: [REDACTED],
          redirect_uri: redirectUrl,
          code,
          grant_type: "authorization_code",
        }),
      })
    const longLivedToken = await exchangeLongLivedToken(
      {
        clientId: settings.clientId,
        clientSecret: [REDACTED],
        version: settings.version,
      },
      res.access_token,
    )
    return { accessToken: [REDACTED], userId: String(res.user_id) }
  })
}

export const exchangeLongLivedToken = (
  settings: {
    clientId: string
    clientSecret: string
    version?: string
  },
  accessToken: string,
): Promise<string> => {
  const endpoint = "access_token"

  return rescue(endpoint, async () => {
    const res: { access_token: string; expires_in: number } =
      await instagramBusinessClient.get(endpoint, {
        searchParams: {
          grant_type: "ig_exchange_token",
          client_secret: [REDACTED],
          access_token: accessToken,
        },
      })

    return res.access_token
  })
}

export async function getInstagramAccount(
  userAccessToken: string,
): Promise<InstagramAccount | null> {
  const endpoint = "me"

  try {
    const res = await rescue(endpoint, async () =>
      instagramBusinessClient.get<{
        id: string
        username: string
        user_id: string
        name?: string
        profile_picture_url?: string
        account_type?: string
      }>(endpoint, {
        searchParams: {
          fields: "id,user_id,username,name,profile_picture_url,account_type",
          access_token: [REDACTED],
        },
      }),
    )

    if (
      !VALID_ACCOUNT_TYPES.includes(
        res.account_type as (typeof VALID_ACCOUNT_TYPES)[number],
      )
    ) {
      logger.warn(
        { account_type: res.account_type },
        `Instagram account is not one of the supported account types: ${VALID_ACCOUNT_TYPES.join(", ")}`,
      )
      return null
    }

    return {
      id: res.id,
      name: res.name ?? res.username,
      username: res.username,
      profile_picture_url: res.profile_picture_url,
      userId: res.user_id,
      accessToken: [REDACTED],
    }
  } catch (error) {
    if (error instanceof InstagramException) {
      logger.warn(error, "Failed to fetch Instagram account during connect")
      return null
    }
    throw error
  }
}

import type { Oauth2Config } from "@chatbotx.io/sdk"
import { ZALO_API_ENDPOINTS, ZALO_OAUTH_BASE_URL } from "../constants"
import { handleZaloError, ZaloException } from "../lib/exception"
import { ZaloHttpClient } from "../lib/http-client"

export function generateAuthUrl(props: Oauth2Config) {
  const { clientId, redirectUrl, stateParams } = props
  const params = new URLSearchParams({
    app_id: clientId,
    redirect_uri: redirectUrl,
    state: btoa(JSON.stringify(stateParams)),
  })

  return `${ZALO_OAUTH_BASE_URL}${ZALO_API_ENDPOINTS.AUTH.PERMISSION}?${params.toString()}`
}

export type ZaloAccessTokenResponse = {
  access_token: string
  refresh_token: string
  expires_in: number
}

export const convertCodeToTokens = (
  setting: Oauth2Config,
  code: string,
): Promise<ZaloAccessTokenResponse> =>
  handleZaloError("Convert code to tokens", async () => {
    const client = ZaloHttpClient.createOAuthClient()

    return await client.post<ZaloAccessTokenResponse>(
      ZALO_API_ENDPOINTS.AUTH.ACCESS_TOKEN,
      {
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
          secret_key: setting.clientSecret,
        },
        body: new URLSearchParams({
          code,
          app_id: setting.clientId,
          redirect_uri: setting.redirectUrl,
          grant_type: "authorization_code",
        }),
      },
    )
  })

export const refreshAccessToken = (
  setting: Oauth2Config,
  refreshToken: string,
): Promise<ZaloAccessTokenResponse> =>
  handleZaloError("Refresh access token", async () => {
    const client = ZaloHttpClient.createOAuthClient()

    return await client.post<ZaloAccessTokenResponse>(
      ZALO_API_ENDPOINTS.AUTH.ACCESS_TOKEN,
      {
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
          secret_key: setting.clientSecret,
        },
        body: new URLSearchParams({
          app_id: setting.clientId,
          app_secret: [REDACTED],
          refresh_token: [REDACTED],
          grant_type: "refresh_token",
        }),
      },
    )
  })

export type ZaloOAProfileResponse = {
  data: {
    oa_id: string
    name: string
    description: string
    avatar: string
  }
  error: number
  message: string
}

export const getZaloOAProfile = (
  accessToken: string,
): Promise<ZaloOAProfileResponse["data"]> =>
  handleZaloError("Get OA profile", async () => {
    const client = ZaloHttpClient.createAuthenticatedClient(accessToken)
    const result = await client.get<ZaloOAProfileResponse>(
      ZALO_API_ENDPOINTS.OA.GET_PROFILE,
    )

    if (result.error !== 0) {
      throw new ZaloException(
        result.message,
        undefined,
        result.error,
        undefined,
        undefined,
        { response: { error: result } },
      )
    }

    return result.data
  })
